<?php
declare(strict_types=1);
$root=dirname(__DIR__);spl_autoload_register(static function(string$class)use($root):void{$p='Babanoell\\Finance\\';if(!str_starts_with($class,$p))return;$f=$root.'/src/'.str_replace('\\','/',substr($class,strlen($p))).'.php';if(is_file($f))require$f;});
$tests=[];$add=static function(string$n,callable$f)use(&$tests){$tests[$n]=$f;};$assert=static function(bool$v,string$m='assertion failed'){if(!$v)throw new RuntimeException($m);};$eq=static function(mixed$a,mixed$b){if($a!==$b)throw new RuntimeException(var_export($a,true).' !== '.var_export($b,true));};
$add('release identifies Finance 1.0.1',function()use($root,$eq){$v=require$root.'/config/version.php';$eq('finance',$v['service']);$eq('1.0.1',$v['version']);$eq('finance-service',$v['phase']);});
$add('finance boundary owns financial domains',function()use($assert){$c=Babanoell\Finance\Platform\ServiceBoundary::describe();foreach(['bank_settlements','merchant_settlements','settlement_cycles','financial_receipts','financier_payments','financial_reconciliation']as$x)$assert(in_array($x,$c['owns'],true));});
$add('finance boundary forbids loan merchant and binary ownership',function()use($assert){$c=Babanoell\Finance\Platform\ServiceBoundary::describe();foreach(['loan_status_machine','loan_calculation','merchant_master_data','document_binary_storage']as$x)$assert(in_array($x,$c['forbidden'],true));});
$add('finance depends on identity loans partners documents',function()use($assert){$c=Babanoell\Finance\Platform\ServiceBoundary::describe();foreach(['identity','loans','partners','documents']as$x)$assert(in_array($x,$c['depends_on'],true));});
$add('finance migration files expose three unique versions',function()use($root,$assert,$eq){$files=glob($root.'/database/migrations/*.php')?:[];sort($files);$seen=[];foreach($files as$f){$m=require$f;$assert($m instanceof Babanoell\Finance\Database\Migration);$assert(!isset($seen[$m->version()]));$seen[$m->version()]=1;}$eq(3,count($seen));});
$add('finance schema has no cross service foreign keys',function()use($root,$assert){$s='';foreach(glob($root.'/database/migrations/*.php')?:[]as$f)$s.=file_get_contents($f);foreach(['REFERENCES loan_requests','REFERENCES merchants','REFERENCES documents','REFERENCES users']as$n)$assert(!str_contains($s,$n),$n);});
$add('bank settlement is one row per request with history',function()use($root,$assert){$s=file_get_contents($root.'/database/migrations/202610010001_create_finance_core.php');$assert(str_contains($s,'UNIQUE KEY uq_bank_settlement_request'));$assert(str_contains($s,'bank_settlement_history'));});
$add('merchant settlement is one row per request with history',function()use($root,$assert){$s=file_get_contents($root.'/database/migrations/202610010001_create_finance_core.php');$assert(str_contains($s,'UNIQUE KEY uq_merchant_settlement_request'));$assert(str_contains($s,'merchant_settlement_history'));});
$add('financier payment is one row per request with history',function()use($root,$assert){$s=file_get_contents($root.'/database/migrations/202610010001_create_finance_core.php');$assert(str_contains($s,'UNIQUE KEY uq_financier_payment_request'));$assert(str_contains($s,'financier_payment_history'));});
$add('cycle item prevents double assignment',function()use($root,$assert){$s=file_get_contents($root.'/database/migrations/202610010002_create_cycles_receipts.php');$assert(str_contains($s,'UNIQUE KEY uq_settlement_item_request'));});
$add('repository uses FOR UPDATE for financial concurrency',function()use($root,$assert){$s=file_get_contents($root.'/src/Repository/PdoFinanceRepository.php');$assert(substr_count($s,'FOR UPDATE')>=5);});
$add('closed cycle is immutable until controlled reopen',function()use($root,$assert){$s=file_get_contents($root.'/src/Repository/PdoFinanceRepository.php');$assert(str_contains($s,"status']!=='open'"));$assert(str_contains($s,'reopenCycle'));$assert(str_contains($s,'دلیل بازگشایی الزامی است'));});
$add('receipts store document references only',function()use($root,$assert){$s=file_get_contents($root.'/database/migrations/202610010002_create_cycles_receipts.php');$assert(str_contains($s,'document_id CHAR(26)'));$assert(!str_contains(strtolower($s),'blob'));});
$add('reconciliation and finance audit exist',function()use($root,$assert){$s=file_get_contents($root.'/database/migrations/202610010003_create_reconciliation_audit.php');foreach(['finance_reconciliation_items','finance_events','request_id','caller_service']as$n)$assert(str_contains($s,$n));});
$add('API exposes settlement cycle receipt and reconciliation routes',function()use($root,$assert){$s=file_get_contents($root.'/public/index.php');foreach(['/bank-settlement','/merchant-settlement','/financier-payment','/api/v1/cycles','/api/v1/receipts','/api/v1/reconciliation','/api/v1/import/loans-shadow']as$n)$assert(str_contains($s,$n),$n);});
$add('shadow import uses HTTP client not Loans DB',function()use($root,$assert){$s=file_get_contents($root.'/src/Service/FinanceService.php');$assert(str_contains($s,'financeShadow'));$assert(!str_contains($s,'noeelir_loans'));});
$add('service auth includes finance caller',function()use($root,$assert){$s=file_get_contents($root.'/src/Platform/ServiceAuth.php');$assert(str_contains($s,"'finance'"));});
