$add('installer configures four dependencies and independent DB',function()use($root,$assert){$s=file_get_contents(is_file($root.'/public/install.php')?$root.'/public/install.php':$root.'/public/install.php.locked');foreach(['FINANCE_DB_NAME','FINANCE_IDENTITY_BASE_URL','FINANCE_LOANS_BASE_URL','FINANCE_PARTNERS_BASE_URL','FINANCE_DOCUMENTS_BASE_URL']as$n)$assert(str_contains($s,$n),$n);});
