$add('batch 1 finance reset requires admin confirmed version and checks cycle membership',function()use($root,$assert){$r=file_get_contents($root.'/src/Repository/PdoFinanceRepository.php');$idx=file_get_contents($root.'/public/index.php');foreach(['function resetMerchantSettlement','FOR UPDATE','settlement_cycle_items','row_version=row_version+1',"status='awaiting_date'",'settlement_date=NULL','merchant_settlement.admin_reset']as $n)$assert(str_contains($r,$n),$n);foreach(['/merchant-settlement/reset','!$admin','adminResetMerchantSettlement']as $n)$assert(str_contains($idx,$n),$n);});
